// Client-side re-implementation of the trained sklearn pipeline's decision
// function, for the static GitHub Pages demo (which has no backend to call).
//
// The saved model is: ColumnTransformer(OneHotEncoder, StandardScaler) ->
// LogisticRegression. That whole pipeline reduces to one linear combination
// of 0/1 one-hot indicators and scaled numeric values, passed through a
// sigmoid — so this file evaluates exactly that, using the real fitted
// weights in model_params.js (generated by docs/export_model_params.py from
// the same models/churn_logistic_model.joblib the FastAPI backend loads).
// It is not a separate or re-trained model.

function sigmoid(z) {
  return 1 / (1 + Math.exp(-z));
}

function churnProbability(customer, params) {
  let z = params.intercept;
  for (const term of params.terms) {
    if (term.type === "onehot") {
      if (String(customer[term.field]) === String(term.value)) {
        z += term.coef;
      }
      // A category with no matching term (shouldn't happen from the <select>
      // inputs in index.html) contributes 0, mirroring OneHotEncoder's
      // handle_unknown="ignore" behavior in the real pipeline.
    } else if (term.type === "scaled") {
      const value = Number(customer[term.field]);
      z += ((value - term.mean) / term.scale) * term.coef;
    }
  }
  return sigmoid(z);
}

function riskCategory(probability, threshold, mediumCutoff) {
  if (probability >= mediumCutoff) return "High";
  if (probability >= threshold) return "Medium";
  return "Low";
}

function predictChurn(customer, params) {
  const probability = churnProbability(customer, params);
  const prediction = probability >= params.threshold ? 1 : 0;
  return {
    churn_probability: probability,
    prediction,
    label: prediction === 1 ? "Likely to Churn" : "Likely to Stay",
    threshold: params.threshold,
    risk_category: riskCategory(probability, params.threshold, params.medium_risk_cutoff),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { churnProbability, predictChurn, riskCategory, sigmoid };
}
